INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (312382, 13799, 'The Times of India', 'en', '‘Private parts electrocuted’: Wife kills man with help from lover in south Delhi', 'https://timesofindia.indiatimes.com/city/delhi/private-parts-electrocuted-wife-kills-man-with-help-from-lover-in-south-delhi/articleshow/133195611.cms', 'A horrifying scene unfolded in a quiet home where a man was discovered murdered, initially thought to be the work of a burglar. However, police uncovered a dark plot involving the man''s wife and her lover, who conspired to kill him. They sedated him, used electrocution, and artfully manipulated the scene to resemble a robbery.', 'https://static.toiimg.com/photo/msid-133195647,imgsize-121303.cms', '2026-08-13T01:29:45+00:00', '2026-08-13T02:00:40.840521'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
