INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (320919, 13806, 'The Guardian', 'en', 'UK records hottest day of year as fifth summer heatwave reaches peak', 'https://www.theguardian.com/environment/2026/aug/13/uk-records-hottest-day-of-the-year-fifth-summer-heatwave-peak', 'Kew Gardens in London hits 38.1C and 40C-plus recorded in parts of Europe with continent trapped under heat dome Europe heatwave – latest updates The UK has recorded its hottest day of the year so far with a provisional temperature of 38.1C in southern England as Europe sweltered under a major heat dome. As temperatures on the continent surpassed 40C at the peak of the summer’s fifth heatwave, the thermometer at Kew Gardens in west London on Thursday surpassed the previous high of 38C on 28 June, the Met Office said. Continue reading...', 'https://i.guim.co.uk/img/media/e5a0b134c2f79a080eeefd252497e8eabbb43d45/943_0_6265_5011/master/6265.jpg?width=140&quality=85&auto=format&fit=max&s=f05731d8a2f578adece5a457ec1133de', '2026-08-13T15:48:53+00:00', '2026-08-13T22:50:37.983542'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
