INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (317623, 13820, 'The Economic Times', 'en', 'Euro zone bonds little changed as oil prices steady', 'https://economictimes.indiatimes.com/markets/bonds/euro-zone-bonds-little-changed-as-oil-prices-steady/articleshow/133203702.cms', 'Euro zone bond yields showed little movement on Thursday, coinciding with steady oil prices. Recent U.S. inflation data has lessened the market''s anticipation of a Federal Reserve rate increase in the upcoming month. With energy dialogues taking place and the potential reopening of the Strait of Hormuz, investors are on alert. Rising oil prices could lead to continued interest rate hikes by the ECB.', 'https://img.etimg.com/photo/msid-133203702,imgsize-20004.cms', '2026-08-13T07:27:00+00:00', '2026-08-13T08:16:25.705454'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (317624, 13820, 'The Economic Times', 'en', 'Global Market: Japan wholesale inflation stays elevated, bolstering September rate hike bets', 'https://economictimes.indiatimes.com/markets/us-stocks/news/global-market-japan-wholesale-inflation-stays-elevated-bolstering-september-rate-hike-bets/articleshow/133203477.cms', 'Japan’s wholesale inflation stayed elevated in July, with producer prices rising 7.2% year-on-year, reinforcing expectations of a September Bank of Japan rate hike. Broad-based cost pressures, higher import prices and yen weakness are raising inflation risks, while stronger metal and raw-material costs could further pressure consumer prices and accelerate monetary tightening.', 'https://img.etimg.com/photo/msid-133203477,imgsize-140448.cms', '2026-08-13T07:24:17+00:00', '2026-08-13T08:16:25.755149'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (317625, 13820, 'The Economic Times', 'en', 'Global Market: Japanese bond yields hold near highs as markets brace for BOJ rate hike', 'https://economictimes.indiatimes.com/markets/us-stocks/news/global-market-japanese-bond-yields-hold-near-highs-as-markets-brace-for-boj-rate-hike/articleshow/133203276.cms', 'Japanese government bond yields remained broadly steady as investors increased bets on a possible Bank of Japan rate hike in September. Short-term yields stayed near multi-year highs, while longer-term yields rose amid fiscal concerns and expected government spending. Markets now largely anticipate further monetary tightening, though fiscal risks could limit yen gains despite higher rates.', 'https://img.etimg.com/photo/msid-133203276,imgsize-43216.cms', '2026-08-13T07:15:53+00:00', '2026-08-13T08:16:25.785636'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
