INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (310903, 13838, 'The Hindu', 'en', 'Rape survivors don’t need court approval to terminate pregnancies up to 24 weeks: Madhya Pradesh High Court', 'https://www.thehindu.com/news/national/madhya-pradesh/rape-survivors-dont-need-court-approval-to-terminate-pregnancies-up-to-24-weeks-madhya-pradesh-high-court/article71337419.ece', 'The High Court cited a verdict its Division Bench in Jabalpur had earlier delivered, clarifying that under the provisions of the Medical Termination of Pregnancy (MTP) Act, 1971, survivors of sexual assault, rape, or incest, with pregnancies up to 24 weeks, who want to undergo an abortion do not require judicial proceedings under Article 226 of the Constitution', 'https://th-i.thgim.com/public/incoming/tcndn5/article71338376.ece/alternates/LANDSCAPE_1200/IMG_NCLAT-approves-_G51D_2_1_8TDJ40P5.jpg', '2026-08-12T21:17:52+00:00', '2026-08-12T23:42:13.831073'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
