INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (324195, 13867, 'Euronews', 'en', 'Survivors tell of horror of Zimbabwe ferry sinking as police say death toll hits 46', 'http://www.euronews.com/2026/08/13/survivors-tell-of-horror-of-zimbabwe-ferry-sinking-as-police-say-death-toll-hits-46', 'The overloaded government ferry, a vital link for villagers and fish traders around the vast Lake Kariba, overturned in choppy waters on Tuesday in one of the country''s worst passenger boat disasters.', '', '2026-08-13T16:57:26+00:00', '2026-08-13T22:55:30.546604'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
