INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (329532, 13867, 'France 24', 'en', 'Ferry sinking kills 46 in rural Zimbabwe', 'https://www.france24.com/en/ferry-sinking-kills-46-in-rural-zimbabwe', 'In Zimbabwe, hundreds of people have attended a memorial service following a ferry disaster on Lake Kariba that claimed at least 46 lives. The boat was a vital link for villagers and fish traders around the vast lake, but was reportedly overloaded when it ran into trouble on Tuesday. Laurent Berstecher has the details.', 'https://s.france24.com/media/display/cf099394-97d3-11f1-9ae3-005056a90284/w:1024/p:16x9/EN-20260814-132242-132406-CS.jpg', '2026-08-14T11:37:37+00:00', '2026-08-14T14:58:37.137300'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
