INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (340796, 13867, 'Le Monde', 'en', 'Zimbabwe ferry disaster death toll rises to 72 as search continues', 'https://www.lemonde.fr/en/international/article/2026/08/15/zimbabwe-ferry-disaster-death-toll-rises-to-72-as-search-continues_6756551_4.html', 'The death toll from Zimbabwe''s worst ferry disaster has risen to 72 after authorities recovered 25 more bodies from Lake Kariba, as rescuers continued searching the waters for victims.', 'https://img.lemde.fr/2026/08/14/626/0/7512/3756/644/322/60/0/e240852_ftp-1-66gv46w139si-14a8662b42784993931d6a86f5e3a371-1-194b95db9cfe42c9967624080a97c818.jpg', '2026-08-15T21:58:50+00:00', '2026-08-16T00:08:06.621251'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
